        String field = "name";
        JSType expected = jstypeSystem.getTypeWithProperty(field, type);
        Assert.assertNotNull(expected);
        Assert.assertEquals(type, expected);
    }

    @Test
    public void testGetTypeWithProperty_autoboxing() {
        JSType type = ObjectType.cast(jstypeSystem.registry.getNativeType(JSTypeNative.NUMBER_TYPE));
        String field = "name";
        JSType expected = jstypeSystem.getTypeWithProperty(field, type);
        Assert.assertNull(expected);
    }

    @Test
    public void testGetTypeWithProperty_prototype() {
        JSType type = ObjectType.cast(jstypeSystem.registry.getNativeType(JSTypeNative.OBJECT_TYPE));
        String field = "prototype";
        JSType expected = jstypeSystem.getTypeWithProperty(field, type);
        Assert.assertNull(expected);
    }

    @Test
    public void testGetTypeWithProperty_noMatch() {
        JSType type = ObjectType.cast(jstypeSystem.registry.getNativeType(JSTypeNative.STRING_TYPE));
        String field = "name";
        JSType expected = jstypeSystem.getTypeWithProperty(field, type);
        Assert.assertNull(expected);
    }

    @Test
    public void testGetTypeWithProperty_subtypeMatch() {
        JSType type = ObjectType.cast(jstypeSystem.registry.getNativeType(JSTypeNative.OBJECT_TYPE));
        String field = "name";
        JSType subtype = ObjectType.cast(jstypeSystem.registry.getNativeType(JSTypeNative.OBJECT_TYPE));
        subtype.setProperty(field, JSTypeNative.STRING_TYPE);
        JSType expected = jstypeSystem.getTypeWithProperty(field, type);
        Assert.assertNotNull(expected);
        Assert.assertEquals(subtype, expected);
    }

    @Test
    public void testGetTypeWithProperty_noMatchButRegistryFinds() {
        JSType type = ObjectType.cast(jstypeSystem.registry.getNativeType(JSTypeNative.OBJECT_TYPE));
        String field = "name";
        JSType maybeType = jstypeSystem.registry.getGreatestSubtypeWithProperty(type, field);
        JSType expected = ObjectType.cast(maybeType);
        Assert.assertNotNull(expected);
        Assert.assertEquals(expected, maybeType);
    }
